// Đọc dữ liệu từ buffer file JSON
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data'); // Đổi 'data' thành field binary tương ứng nếu khác
const jsonString = buffer.toString('utf-8');
const rawWorkflow = JSON.parse(jsonString);

// Chỉ lấy các cài đặt hợp lệ trong settings để tránh bị API từ chối
const rawSettings = rawWorkflow.settings || {};
const cleanSettings = {
  executionOrder: rawSettings.executionOrder || 'v1',
  ...(rawSettings.timezone && { timezone: rawSettings.timezone }),
  ...(rawSettings.saveExecutionProgress !== undefined && { saveExecutionProgress: rawSettings.saveExecutionProgress }),
  ...(rawSettings.saveDataErrorExecution !== undefined && { saveDataErrorExecution: rawSettings.saveDataErrorExecution }),
  ...(rawSettings.saveDataSuccessExecution !== undefined && { saveDataSuccessExecution: rawSettings.saveDataSuccessExecution }),
  ...(rawSettings.saveManualExecutions !== undefined && { saveManualExecutions: rawSettings.saveManualExecutions }),
  ...(rawSettings.callerPolicy && { callerPolicy: rawSettings.callerPolicy }),
  ...(rawSettings.errorWorkflow && { errorWorkflow: rawSettings.errorWorkflow })
};

// Đóng gói đối tượng workflow sạch
const cleanWorkflow = {
  name: rawWorkflow.name || 'Imported Workflow',
  nodes: rawWorkflow.nodes || [],
  connections: rawWorkflow.connections || {},
  settings: cleanSettings,
  staticData: rawWorkflow.staticData || null
};

return {
  json: cleanWorkflow
};

