// Đọc dữ liệu JSON từ Google Drive / nút trước
const binaryData = await this.helpers.getBinaryDataBuffer(0, 'data');
const fileContent = JSON.parse(binaryData.toString('utf8'));

// Lọc bỏ thuộc tính thừa trong settings
let cleanSettings = {};
if (fileContent.settings) {
  // Chỉ giữ lại các trường chuẩn mà n8n Public API hỗ trợ
  if (fileContent.settings.executionOrder) cleanSettings.executionOrder = fileContent.settings.executionOrder;
  if (fileContent.settings.binaryMode) cleanSettings.binaryMode = fileContent.settings.binaryMode;
  if (fileContent.settings.timezone) cleanSettings.timezone = fileContent.settings.timezone;
  if (fileContent.settings.saveExecutionProgress !== undefined) cleanSettings.saveExecutionProgress = fileContent.settings.saveExecutionProgress;
  if (fileContent.settings.saveDataErrorExecution !== undefined) cleanSettings.saveDataErrorExecution = fileContent.settings.saveDataErrorExecution;
  if (fileContent.settings.saveDataSuccessExecution !== undefined) cleanSettings.saveDataSuccessExecution = fileContent.settings.saveDataSuccessExecution;
  if (fileContent.settings.saveManualExecutions !== undefined) cleanSettings.saveManualExecutions = fileContent.settings.saveManualExecutions;
  if (fileContent.settings.callerPolicy) cleanSettings.callerPolicy = fileContent.settings.callerPolicy;
  if (fileContent.settings.errorWorkflow) cleanSettings.errorWorkflow = fileContent.settings.errorWorkflow;
}

return {
  json: {
    name: fileContent.name || 'Imported Workflow',
    nodes: fileContent.nodes || [],
    connections: fileContent.connections || {},
    settings: cleanSettings
  }
};

// Đọc dữ liệu JSON từ Google Drive / nút trước
const binaryData = await this.helpers.getBinaryDataBuffer(0, 'data');
const fileContent = JSON.parse(binaryData.toString('utf8'));

// Xóa hoặc làm sạch trường settings gây lỗi n8n API
delete fileContent.settings;

return {
  json: {
    name: fileContent.name || 'Imported Workflow',
    nodes: fileContent.nodes || [],
    connections: fileContent.connections || {},
    settings: {} // Đẩy settings rỗng để tránh dính thuộc tính không hợp lệ
  }
};
